// Um pedido à IA por perfil ativo que ainda não tem a dica de hoje.
const NL = String.fromCharCode(10);
const lista = $input.all().flatMap(i => Array.isArray(i.json) ? i.json : (Array.isArray(i.json && i.json.data) ? i.json.data : [i.json]));
const brl = v => 'R$ ' + Number(v).toFixed(2).replace('.', ',');
const out = [];
for (const p of lista) {
  if (!p || !p.autor) continue;
  const cambio = p.incluir_cambio && p.usd && p.usd.valor ? 'Dólar hoje: ' + brl(p.usd.valor) + ' (' + (Number(p.usd.variacao_pct) >= 0 ? '+' : '') + Number(p.usd.variacao_pct || 0).toFixed(2) + '% no dia)' + (p.eur && p.eur.valor ? '; euro: ' + brl(p.eur.valor) : '') + '.' : '';
  const ant = Array.isArray(p.anteriores) && p.anteriores.length ? NL + 'IDEIAS JÁ ENVIADAS NOS ÚLTIMOS DIAS (não repita tema nem formato seguidos):' + NL + p.anteriores.map(t => '- ' + String(t).slice(0, 220)).join(NL) : '';
  const sistema = 'Você escreve, em português do Brasil, uma dica curta para o bom dia de um cliente do Dyno (assistente no WhatsApp). Tema do cliente: ' + p.tema + '.' + NL + (p.instrucao || '') + NL + 'Formato da resposta: texto puro para WhatsApp, no máximo 7 linhas, sem título, sem saudação, sem markdown além de *negrito* no gancho. Comece com o emoji 💡 e o gancho em negrito. Nada de números inventados, promessas de ganho ou nomes de pessoas reais.' + ant;
  const user = (cambio ? cambio + NL : '') + 'Escreva a ideia de conteúdo de hoje para ' + p.autor + '.';
  out.push({ json: { autor: p.autor, cambio, tarefa: 'simples', origem: 'bom_dia_ideia', sistema, mensagens: [{ role: 'user', content: user }], max_tokens: 400 } });
}
return out;

// Junta a cotação e a ideia; se a IA falhar, manda só a cotação.
const NL = String.fromCharCode(10);
const out = [];
$input.all().forEach((it, i) => {
  const r = it.json || {};
  const ped = $('Montar pedido IA').all()[i].json;
  let ideia = r.ok ? String(r.texto || '').trim() : '';
  ideia = ideia.replace(/^```[a-z]*\s*|```$/g, '').trim().split(NL).slice(0, 8).join(NL);
  const partes = [];
  if (ped.cambio) partes.push('💵 ' + ped.cambio);
  if (ideia) partes.push(ideia);
  if (!partes.length) return;
  out.push({ json: { p_autor: ped.autor, p_texto: partes.join(NL + NL) } });
});
return out;
